// Normalise la demande reçue du site et ouvre la fiche de cadrage.
const cfg = $('Configuration').first().json;
const b = cfg.body ?? {};
const clean = (v, max = 4000) => String(v ?? '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, ' ').trim().slice(0, max);
const now = new Date();
const projectId = 'AVR-' + now.toISOString().slice(0, 10).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();

const types = { contact: 'Question générale', project: 'Demande de projet', partnership: 'Demande de partenariat' };
const sectors = {
  professional: 'Services professionnels', accounting: 'Comptabilité et administration',
  hr: 'Ressources humaines et recrutement', realEstate: 'Immobilier',
  ecommerce: 'Commerce électronique', publicProcurement: 'Marchés publics', other: 'Autre / non précisé',
};

// Questions de cadrage de base, complétées selon le secteur.
const questions = [
  'Quel résultat concret attendez-vous, et comment saurez-vous que c’est réussi ?',
  'Qui est concerné au quotidien par ce processus ?',
  'Quels outils et fichiers utilisez-vous aujourd’hui ?',
  'Quelle est votre échéance et votre marge de manœuvre budgétaire ?',
];
const bySector = {
  accounting: 'Quelles pièces et quels contrôles sont les plus chronophages ?',
  hr: 'Combien de candidatures ou de dossiers traitez-vous par mois ?',
  realEstate: 'Combien d’immeubles, de baux ou d’acquisitions suivez-vous ?',
  ecommerce: 'Quelle plateforme et quels volumes de commandes ?',
  publicProcurement: 'Combien de soumissions préparez-vous par année ?',
  professional: 'Comment le temps et la facturation sont-ils suivis aujourd’hui ?',
};
if (bySector[b.sector]) questions.push(bySector[b.sector]);

return [{ json: {
  projectId,
  stage: '1-comprendre',
  receivedAt: clean(b.receivedAt, 40) || now.toISOString(),
  locale: b.locale === 'en' ? 'en' : 'fr',
  type: b.type in types ? b.type : 'contact',
  typeLabel: types[b.type] ?? types.contact,
  name: clean(b.name, 120),
  email: clean(b.email, 254).toLowerCase(),
  organization: clean(b.organization, 160),
  sector: b.sector in sectors ? b.sector : 'other',
  sectorLabel: sectors[b.sector] ?? sectors.other,
  message: clean(b.message),
  cadrageQuestions: questions,
}}];

