// Le nom et le courriel ne sont jamais envoyés à l'IA (minimisation, Loi 25).
const fiche = $('① Comprendre – Fiche de cadrage').first().json;
const res = $json;
let analysis = null;
let note = '';
if (res.stop_reason === 'refusal') {
  note = 'L’IA a décliné la demande : analyse manuelle requise.';
} else if (Array.isArray(res.content)) {
  // Des blocs « thinking » peuvent précéder la réponse : on lit le bloc texte.
  const text = res.content.find((c) => c.type === 'text')?.text;
  try { analysis = JSON.parse(text); } catch { note = 'Réponse IA illisible : analyse manuelle requise.'; }
} else {
  note = 'Appel IA en erreur (' + (res.error?.message ?? 'inconnue') + ') : analyse manuelle requise.';
}
return [{ json: { ...fiche, stage: '2-analyser', analysisSource: analysis ? 'IA (à vérifier)' : 'manuelle', analysisNote: note,
  analysis: analysis ?? {
    resume: '[À compléter]', objectifs: [], irritants: [], questionsCadrage: fiche.cadrageQuestions,
    pistesSolutions: [], risques: [], priorite: 'moyenne', prochaineEtape: 'Planifier un appel de cadrage.',
  } } }];

// IA désactivée : grille d'analyse à remplir par l'équipe lors de l'appel de cadrage.
const fiche = $json;
return [{ json: { ...fiche, stage: '2-analyser', analysisSource: 'manuelle', analysisNote: 'IA désactivée (useAI = false).',
  analysis: {
    resume: '[À compléter après l’appel de cadrage]',
    objectifs: ['[Objectif 1]'],
    irritants: ['[Irritant observé]'],
    questionsCadrage: fiche.cadrageQuestions,
    pistesSolutions: ['[Piste à évaluer]'],
    risques: ['[Risque ou contrainte]'],
    priorite: 'moyenne',
    prochaineEtape: 'Planifier un appel de cadrage de 30 minutes.',
  } } }];

// Assemble un brouillon de proposition structuré selon la méthode AVORYN.
const d = $json;
const a = d.analysis;
const list = (arr) => (arr && arr.length ? arr.map((x) => '  - ' + x).join('\n') : '  - [À compléter]');
const proposal = [
  'PROPOSITION — ' + d.projectId + ' (brouillon interne)',
  'Client : ' + d.name + (d.organization ? ' — ' + d.organization : '') + ' | ' + d.sectorLabel,
  '',
  '1. Compréhension du besoin', '  ' + a.resume,
  '', '2. Objectifs et critères de réussite', list(a.objectifs),
  '', '3. Irritants identifiés', list(a.irritants),
  '', '4. Démarche proposée',
  '  Comprendre → Analyser → Concevoir → Déployer → Améliorer',
  '  Pistes à évaluer :', list(a.pistesSolutions),
  '', '5. Livrables types',
  '  - Cartographie des processus et diagnostic priorisé',
  '  - Architecture de la solution retenue et plan de mise en œuvre',
  '  - Mise en service par étapes, documentation, transfert de connaissances',
  '', '6. Risques et hypothèses', list(a.risques),
  '', '7. Questions à valider avec le client', list(a.questionsCadrage),
  '', '8. Échéancier et honoraires : [À compléter par l’équipe]',
].join('\n');
return [{ json: { ...d, stage: '3-concevoir', proposal } }];

