// Plan de déploiement par étapes, repris de la proposition approuvée.
const d = $('③ Concevoir – Brouillon de proposition').first().json;
const phases = [
  { phase: 'Lancement', tasks: ['Rencontre de démarrage', 'Confirmer objectifs et critères de réussite', 'Accès aux outils et documents'] },
  { phase: 'Prototype', tasks: ['Construire la première version', 'Tester avec 1 à 2 utilisateurs', 'Ajuster'] },
  { phase: 'Mise en service', tasks: ['Déploiement progressif', 'Documentation', 'Formation des utilisateurs'] },
  { phase: 'Stabilisation', tasks: ['Suivi des incidents', 'Mesure des indicateurs de départ', 'Transfert de connaissances'] },
];
const checklist = phases.map((p, i) => (i + 1) + '. ' + p.phase + '\n' + p.tasks.map((t) => '   [ ] ' + t).join('\n')).join('\n');
return [{ json: { ...d, stage: '4-deployer', approvedAt: new Date().toISOString(), deploymentPlan: phases, checklist } }];
